import { z } from "zod";
import { DSL_VERSION } from "../constants";

// Lesson DSL Schema (specifications/05-lesson-and-lab-engine.md §1–§4).
// Pure data: no executable JavaScript or HTML generated by AI.

/** Word counter helper for enforcing DSL word limits. */
export function countWords(text: string): number {
  if (!text) return 0;
  return text.trim().split(/\s+/).filter(Boolean).length;
}

/** Check that a string contains no unescaped LaTeX control characters (\f, \t, or \n followed by letters). */
export function hasCorruptedLatexEscapes(text: string): boolean {
  // Form feed (\f from unescaped \frac)
  if (/\f/.test(text)) return true;
  // Tab (\t from unescaped \theta, \times, \text, \tau)
  if (/\t/.test(text)) return true;
  // Raw newline followed by letters (\n from unescaped \neq, \nabla, \nu, \not, etc.)
  if (/\r?\n[a-zA-Z]/.test(text)) return true;
  return false;
}

const latexString = z
  .string()
  .refine((val) => !hasCorruptedLatexEscapes(val), {
    message:
      "LaTeX string contains corrupted unescaped control characters (such as unescaped \\frac, \\times, or \\neq)",
  })
  .transform((s) => s.trim())
  .refine((s) => s.length >= 1, {
    message: "LaTeX string cannot be empty",
  });

// ---------------------------------------------------------------------------
// Block Base & Annotation
// ---------------------------------------------------------------------------

const blockBase = z.object({
  id: z.string().regex(/^s[0-9]+b[0-9]+$/, { message: "Block ID must match format s<screen>b<block> (e.g. s1b1)" }),
  source_refs: z.array(z.number().int().positive()).optional(),
});

export const annotationSchema = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("point"), x_expr: z.string().trim().min(1) }),
  z.object({ kind: z.literal("tangent"), at_expr: z.string().trim().min(1), of: z.string().trim().min(1) }),
  z.object({
    kind: z.literal("secant"),
    from_expr: z.string().trim().min(1),
    to_expr: z.string().trim().min(1),
    of: z.string().trim().min(1),
  }),
  z.object({
    kind: z.literal("area"),
    of: z.string().trim().min(1),
    from_expr: z.string().trim().min(1),
    to_expr: z.string().trim().min(1),
  }),
  z.object({ kind: z.literal("vline"), value_expr: z.string().trim().min(1) }),
  z.object({ kind: z.literal("hline"), value_expr: z.string().trim().min(1) }),
]);
export type Annotation = z.infer<typeof annotationSchema>;

// Compiled AST for client-side plot evaluation
export const astNodeSchema: z.ZodType<unknown> = z.lazy(() =>
  z.union([
    z.object({ type: z.literal("num"), value: z.number() }),
    z.object({ type: z.literal("var"), name: z.string() }),
    z.object({ type: z.literal("unary"), op: z.enum(["+", "-"]), arg: astNodeSchema }),
    z.object({
      type: z.literal("binary"),
      op: z.enum(["+", "-", "*", "/", "^"]),
      left: astNodeSchema,
      right: astNodeSchema,
    }),
    z.object({ type: z.literal("call"), fn: z.string(), args: z.array(astNodeSchema) }),
  ]),
);

export const compiledPlotSchema = z.object({
  functions: z.array(astNodeSchema),
  annotations: z.array(z.record(z.string(), astNodeSchema)).optional(),
});
export type CompiledPlot = z.infer<typeof compiledPlotSchema>;

// ---------------------------------------------------------------------------
// Inline Items (Checkpoints)
// ---------------------------------------------------------------------------

export const mcqOptionSchema = z.object({
  id: z.string().trim().min(1),
  md: z.string().trim().min(1),
  why: z.string().trim().min(1),
});

export const inlineItemSchema = z.discriminatedUnion("type", [
  z
    .object({
      type: z.literal("mcq"),
      stem_md: z.string().trim().min(1),
      options: z.array(mcqOptionSchema).min(2).max(6),
      correct: z.string().trim().min(1),
    })
    .refine((data) => data.options.some((opt) => opt.id === data.correct), {
      message: "MCQ correct option ID must match one of the available options",
      path: ["correct"],
    }),
  z.object({
    type: z.literal("numeric"),
    stem_md: z.string().trim().min(1),
    answer_expr: z.string().trim().min(1),
    stated: z.number(),
    unit: z.string().trim().optional(),
    tolerance: z.object({ rel: z.number().positive().optional(), abs: z.number().positive().optional() }).optional(),
    why: z.string().trim().min(1),
  }),
  z.object({
    type: z.literal("expression"),
    stem_md: z.string().trim().min(1),
    answer_expr: z.string().trim().min(1),
    vars: z.array(z.string().regex(/^[a-zA-Z](_[0-9a-z]+)?$/)).min(1),
    domain: z.record(z.string(), z.tuple([z.number(), z.number()])).optional(),
    why: z.string().trim().min(1),
  }),
  z.object({
    type: z.literal("short_text"),
    stem_md: z.string().trim().min(1),
    key_ideas: z.array(z.string().trim().min(1)).min(1),
    why: z.string().trim().min(1),
  }),
  z.object({
    type: z.literal("order"),
    stem_md: z.string().trim().min(1),
    steps: z.array(z.string().trim().min(1)).min(2).max(8),
    why: z.string().trim().min(1),
  }),
  z.object({
    type: z.literal("match"),
    stem_md: z.string().trim().min(1),
    pairs: z
      .array(z.tuple([z.string().trim().min(1), z.string().trim().min(1)]))
      .min(2)
      .max(6),
    why: z.string().trim().min(1),
  }),
]);
export type InlineItem = z.infer<typeof inlineItemSchema>;

// ---------------------------------------------------------------------------
// Block Schemas
// ---------------------------------------------------------------------------

export const proseBlockSchema = blockBase.extend({
  type: z.literal("prose"),
  md: z
    .string()
    .trim()
    .min(1)
    .refine((s) => countWords(s) <= 90, {
      message: "Prose blocks must be <= 90 words",
    }),
});

export const mathBlockSchema = blockBase.extend({
  type: z.literal("math"),
  latex: latexString,
  display: z.boolean().default(true),
  html: z.string().optional(), // Server-added pre-rendered KaTeX
});

export const calloutBlockSchema = blockBase.extend({
  type: z.literal("callout"),
  variant: z.enum(["tip", "mistake", "exam", "realworld"]),
  md: z
    .string()
    .trim()
    .min(1)
    .refine((s) => countWords(s) <= 50, {
      message: "Callout blocks must be <= 50 words",
    }),
});

export const plotFunctionSchema = z.object({
  expr: z.string().trim().min(1),
  role: z.enum(["quantity", "rate", "area", "neutral"]),
  label: z.string().optional(),
});

export const plotParamSchema = z.object({
  name: z.string().regex(/^[a-zA-Z]$/, {
    message:
      "Slider name must be ONE letter (for example a, k or T, not T1 or cp); rename it here and in every plotted expression that uses it",
  }),
  min: z.number(),
  max: z.number(),
  step: z.number().positive(),
  value: z.number(),
  label: z.string().trim().min(1),
  unit: z.string().optional(),
});

export const plotBlockSchema = blockBase.extend({
  type: z.literal("plot"),
  x: z.tuple([z.number(), z.number()]),
  y: z.tuple([z.number(), z.number()]).optional(),
  functions: z.array(plotFunctionSchema).min(1).max(3),
  params: z.array(plotParamSchema).max(3).optional(),
  annotations: z.array(annotationSchema).optional(),
  caption: z.string().optional(),
  compiled: compiledPlotSchema.optional(), // Server-added
});

export const stepperStepSchema = z.object({
  latex: latexString,
  mathjs: z.string().trim().nullable().optional(),
  why: z
    .string()
    .trim()
    .min(1)
    .refine((s) => countWords(s) <= 25, {
      message: "Stepper step 'why' must be <= 25 words",
    }),
});

export const stepperBlockSchema = blockBase.extend({
  type: z.literal("stepper"),
  steps: z.array(stepperStepSchema).min(2).max(8),
  check: z.enum(["equivalence", "equation", "none"]),
});

export const diagramNodeSchema = z.object({
  id: z.string().trim().min(1),
  label: z.string().trim().min(1),
  x: z.number().min(0).max(100),
  y: z.number().min(0).max(100),
  shape: z.enum(["box", "circle", "pill"]),
});

export const diagramEdgeSchema = z.object({
  from: z.string().trim().min(1),
  to: z.string().trim().min(1),
  label: z.string().optional(),
  style: z.enum(["solid", "dashed", "arrow"]).default("solid"),
});

export const diagramBlockSchema = blockBase.extend({
  type: z.literal("diagram"),
  nodes: z.array(diagramNodeSchema).min(1).max(12),
  edges: z.array(diagramEdgeSchema),
  caption: z.string().optional(),
});

export const tableBlockSchema = blockBase.extend({
  type: z.literal("table"),
  columns: z.array(z.string().trim().min(1)).min(1).max(6),
  rows: z.array(z.array(z.string())).min(1).max(8),
});

export const timelineEventSchema = z.object({
  when: z.string().trim().min(1),
  label: z.string().trim().min(1),
  detail: z.string().optional(),
});

export const timelineBlockSchema = blockBase.extend({
  type: z.literal("timeline"),
  events: z.array(timelineEventSchema).min(1).max(10),
});

export const compareBlockSchema = blockBase.extend({
  type: z.literal("compare"),
  left: z.object({ title: z.string().trim().min(1), points: z.array(z.string().trim().min(1)).min(1).max(5) }),
  right: z.object({ title: z.string().trim().min(1), points: z.array(z.string().trim().min(1)).min(1).max(5) }),
});

export const revealBlockSchema = blockBase.extend({
  type: z.literal("reveal"),
  prompt: z.string().trim().min(1),
  md: z.string().trim().min(1),
});

export const flashcardItemSchema = z.object({
  front: z.string().trim().min(1),
  back: z.string().trim().min(1),
});

export const flashcardsBlockSchema = blockBase.extend({
  type: z.literal("flashcards"),
  cards: z.array(flashcardItemSchema).min(1).max(8),
});

export const sourceQuoteBlockSchema = blockBase.extend({
  type: z.literal("source_quote"),
  chunk_id: z.number().int().positive(),
  quote: z
    .string()
    .trim()
    .min(1)
    .refine((s) => countWords(s) <= 40, {
      message: "Source quote must be <= 40 words",
    }),
  page: z.number().int().positive().optional(),
});

export const simBlockSchema = blockBase.extend({
  type: z.literal("sim"),
  lab: z.string().trim().min(1),
  params: z.record(z.string(), z.unknown()).optional(),
  caption: z.string().optional(),
});

export const checkpointBlockSchema = blockBase.extend({
  type: z.literal("checkpoint"),
  item: inlineItemSchema,
  item_id: z.string().uuid().optional(), // Server-added when materialised in items table
});

export const blockSchema = z.discriminatedUnion("type", [
  proseBlockSchema,
  mathBlockSchema,
  calloutBlockSchema,
  plotBlockSchema,
  stepperBlockSchema,
  diagramBlockSchema,
  tableBlockSchema,
  timelineBlockSchema,
  compareBlockSchema,
  revealBlockSchema,
  flashcardsBlockSchema,
  sourceQuoteBlockSchema,
  simBlockSchema,
  checkpointBlockSchema,
]);
export type Block = z.infer<typeof blockSchema>;

// ---------------------------------------------------------------------------
// Screen & Lesson Spec
// ---------------------------------------------------------------------------

export const screenSchema = z.object({
  id: z.string().regex(/^s[0-9]+$/, { message: "Screen ID must match format s<number> (e.g. s1, s2)" }),
  blocks: z.array(blockSchema).min(1).max(3),
});
export type Screen = z.infer<typeof screenSchema>;

/** Full Lesson Specification (DSL v1). */
export const lessonSpecSchema = z
  .object({
    dsl_version: z.literal(DSL_VERSION),
    title: z.string().trim().min(1).max(70),
    objective: z.string().trim().min(5).max(200),
    subject_profile: z.enum(["stem", "social", "humanities"]),
    est_minutes: z.number().int().min(5).max(20),
    screens: z.array(screenSchema).min(3).max(12),
    summary: z.array(z.string().trim().min(1)).min(2).max(4),
    /** Server-added: inline formulas ($…$ in text) pre-rendered by KaTeX, keyed by their LaTeX. */
    math_html: z.record(z.string(), z.string()).optional(),
  })
  .superRefine((lesson, ctx) => {
    // Checkpoint count requirement: >= 2 checkpoints per lesson (05 §3)
    let checkpointCount = 0;
    let interactiveCount = 0;
    const blockIds = new Set<string>();

    for (let sIdx = 0; sIdx < lesson.screens.length; sIdx++) {
      const screen = lesson.screens[sIdx]!;
      for (let bIdx = 0; bIdx < screen.blocks.length; bIdx++) {
        const block = screen.blocks[bIdx]!;
        if (blockIds.has(block.id)) {
          ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: `Duplicate block id '${block.id}' across lesson`,
            path: ["screens", sIdx, "blocks", bIdx, "id"],
          });
        }
        blockIds.add(block.id);

        if (block.type === "checkpoint") {
          checkpointCount++;
        }
        if (["plot", "stepper", "reveal", "flashcards", "sim"].includes(block.type)) {
          interactiveCount++;
        }
      }
    }

    if (checkpointCount < 2) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `Lesson must contain at least 2 checkpoints, but found ${checkpointCount}`,
        path: ["screens"],
      });
    }

    // If subject allows, must have at least 1 interactive block (05 §3)
    if (lesson.subject_profile === "stem" && interactiveCount < 1) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `STEM lessons must contain at least 1 interactive block (plot, stepper, sim, reveal, flashcards)`,
        path: ["screens"],
      });
    }
  });

export type LessonSpec = z.infer<typeof lessonSpecSchema>;
